// The four contracts, in Go's surface syntax.
ch := make(chan Job)          // rendezvous: sender and receiver must meet (capacity 0)
bounded := make(chan Job, 256) // bounded: send blocks when full -> backpressure

go func() {
    for j := range jobs { ch <- j }   // blocking send when full
    close(ch)                          // the SENDER closes; receivers' range ends
}()

for j := range ch { handle(j) }        // terminates on close

// select: multiplex, cancel, timeout, and disable a case with nil.
select {
case j := <-ch:      process(j)
case <-ctx.Done():  return ctx.Err()    // cancellation: never block forever
case <-time.After(2 * time.Second):    return ErrTimeout
case <-nil:                             // a nil channel blocks forever: disables the case
}

// Directional types make the contract a compile-time check:
func produce(out chan<- Job) { /* may only send */ }
func consume(in <-chan Job)   { /* may only receive */ }
